class VirtualFS:
    """In-memory virtual file system."""

    def __init__(self):
        self.files = {}
        self.dirs = {'/'}
        self.metadata = {}

    def mkdir(self, path):
        path = self._normalize(path)
        parts = path.strip('/').split('/')
        current = ''
        for part in parts:
            current += '/' + part
            self.dirs.add(current)
        return True

    def write_file(self, path, content):
        path = self._normalize(path)
        parent = '/'.join(path.rsplit('/', 1)[:-1]) or '/'
        if parent != '/' and parent not in self.dirs:
            self.mkdir(parent)
        self.files[path] = content
        import time
        self.metadata[path] = {
            'size': len(content),
            'created': time.time(),
            'modified': time.time()
        }

    def read_file(self, path):
        path = self._normalize(path)
        if path not in self.files:
            raise FileNotFoundError(f"File not found: {path}")
        return self.files[path]

    def delete_file(self, path):
        path = self._normalize(path)
        if path in self.files:
            del self.files[path]
            if path in self.metadata:
                del self.metadata[path]
            return True
        return False

    def exists(self, path):
        path = self._normalize(path)
        return path in self.files or path in self.dirs

    def list_dir(self, path='/'):
        path = self._normalize(path)
        if path != '/' and path not in self.dirs:
            return []
        prefix = path if path == '/' else path + '/'
        items = set()
        for f in self.files:
            if f.startswith(prefix):
                rest = f[len(prefix):]
                if '/' in rest:
                    items.add(rest.split('/')[0] + '/')
                else:
                    items.add(rest)
        for d in self.dirs:
            if d.startswith(prefix) and d != path:
                rest = d[len(prefix):]
                if '/' not in rest:
                    items.add(rest + '/')
        return sorted(items)

    def get_size(self, path):
        path = self._normalize(path)
        if path in self.metadata:
            return self.metadata[path]['size']
        return 0

    def tree(self, path='/', depth=0):
        items = self.list_dir(path)
        lines = []
        for item in items:
            lines.append('  ' * depth + item)
            if item.endswith('/'):
                sub = path + ('/' if not path.endswith('/') else '') + item.rstrip('/')
                lines.extend(self.tree(sub, depth + 1))
        return lines

    def _normalize(self, path):
        if not path.startswith('/'):
            path = '/' + path
        while '//' in path:
            path = path.replace('//', '/')
        if path != '/' and path.endswith('/'):
            path = path.rstrip('/')
        return path


class FileWatcher:
    """Watch files for changes."""

    def __init__(self):
        self.watches = {}
        self.snapshots = {}
        self.events = []

    def watch(self, path, callback):
        wid = f"w_{len(self.watches)}"
        self.watches[wid] = {'path': path, 'callback': callback, 'active': True}
        return wid

    def unwatch(self, wid):
        if wid in self.watches:
            self.watches[wid]['active'] = False
            return True
        return False

    def snapshot(self, vfs):
        snap = {}
        for path, content in vfs.files.items():
            snap[path] = hash(content)
        self.snapshots = snap
        return len(snap)

    def check_changes(self, vfs):
        changes = []
        current = {}
        for path, content in vfs.files.items():
            current[path] = hash(content)
        for path, h in current.items():
            if path not in self.snapshots:
                changes.append({'type': 'created', 'path': path})
            elif self.snapshots[path] != h:
                changes.append({'type': 'modified', 'path': path})
        for path in self.snapshots:
            if path not in current:
                changes.append({'type': 'deleted', 'path': path})
        self.events.extend(changes)
        self._notify(changes)
        self.snapshots = current
        return changes

    def _notify(self, changes):
        for change in changes:
            for wid, w in self.watches.items():
                if w['active'] and change['path'].startswith(w['path']):
                    w['callback'](change)

    def get_events(self):
        return list(self.events)


class PathResolver:
    """Resolve and manipulate file paths."""

    def __init__(self, root='/'):
        self.root = root
        self.aliases = {}
        self.cwd = root

    def resolve(self, path):
        if path.startswith('~'):
            for alias, target in self.aliases.items():
                if path.startswith(alias):
                    path = target + path[len(alias):]
                    break
        if not path.startswith('/'):
            path = self.cwd + '/' + path
        parts = []
        for part in path.split('/'):
            if part == '..':
                if parts:
                    parts.pop()
            elif part and part != '.':
                parts.append(part)
        return '/' + '/'.join(parts)

    def add_alias(self, alias, target):
        self.aliases[alias] = target

    def join(self, *parts):
        return '/'.join(p.strip('/') for p in parts if p)

    def dirname(self, path):
        if '/' not in path or path == '/':
            return '/'
        return path.rsplit('/', 1)[0] or '/'

    def basename(self, path):
        return path.rsplit('/', 1)[-1]

    def extension(self, path):
        name = self.basename(path)
        if '.' in name:
            return name.rsplit('.', 1)[-1]
        return ''

    def cd(self, path):
        self.cwd = self.resolve(path)
        return self.cwd

    def split(self, path):
        return [p for p in path.split('/') if p]

    def is_absolute(self, path):
        return path.startswith('/')


