# ============================================================

class StringProcessor:
    """Advanced string manipulation and analysis."""

    def __init__(self):
        self.operations = 0

    def pad(self, s, width, char=' ', align='left'):
        self.operations += 1
        if align == 'left':
            return s.ljust(width, char)
        elif align == 'right':
            return s.rjust(width, char)
        elif align == 'center':
            return s.center(width, char)
        return s

    def truncate(self, s, max_len, suffix='...'):
        self.operations += 1
        if len(s) <= max_len:
            return s
        return s[:max_len - len(suffix)] + suffix

    def camel_to_snake(self, s):
        self.operations += 1
        result = []
        for i, ch in enumerate(s):
            if ch.isupper() and i > 0:
                result.append('_')
            result.append(ch.lower())
        return ''.join(result)

    def snake_to_camel(self, s):
        self.operations += 1
        parts = s.split('_')
        return parts[0] + ''.join(p.capitalize() for p in parts[1:])

    def slug(self, s):
        self.operations += 1
        result = []
        for ch in s.lower():
            if ch.isalnum():
                result.append(ch)
            elif ch in (' ', '-', '_'):
                if result and result[-1] != '-':
                    result.append('-')
        return ''.join(result).strip('-')

    def word_count(self, s):
        self.operations += 1
        return len(s.split())

    def char_frequency(self, s):
        self.operations += 1
        freq = {}
        for ch in s:
            freq[ch] = freq.get(ch, 0) + 1
        return dict(sorted(freq.items(), key=lambda x: -x[1]))

    def reverse_words(self, s):
        self.operations += 1
        return ' '.join(s.split()[::-1])

    def is_palindrome(self, s):
        self.operations += 1
        cleaned = ''.join(ch.lower() for ch in s if ch.isalnum())
        return cleaned == cleaned[::-1]

    def levenshtein(self, a, b):
        self.operations += 1
        if len(a) < len(b):
            return self.levenshtein(b, a)
        if len(b) == 0:
            return len(a)
        prev_row = list(range(len(b) + 1))
        for i, ca in enumerate(a):
            curr_row = [i + 1]
            for j, cb in enumerate(b):
                ins = prev_row[j + 1] + 1
                dl = curr_row[j] + 1
                sub = prev_row[j] + (0 if ca == cb else 1)
                curr_row.append(min(ins, dl, sub))
            prev_row = curr_row
        return prev_row[-1]

    def get_stats(self):
        return {'operations': self.operations}


class RegexEngine:
    """Simple regex-like pattern matching engine."""

    def __init__(self):
        self.compiled = {}
        self.match_count = 0

    def compile(self, pattern):
        tokens = self._tokenize(pattern)
        self.compiled[pattern] = tokens
        return pattern

    def _tokenize(self, pattern):
        tokens = []
        i = 0
        while i < len(pattern):
            ch = pattern[i]
            if ch == '.':
                tokens.append(('any', None))
            elif ch == '*' and tokens:
                prev = tokens.pop()
                tokens.append(('star', prev))
            elif ch == '+' and tokens:
                prev = tokens.pop()
                tokens.append(('plus', prev))
            elif ch == '?'  and tokens:
                prev = tokens.pop()
                tokens.append(('opt', prev))
            elif ch == '[':
                j = pattern.index(']', i)
                chars = pattern[i+1:j]
                tokens.append(('class', chars))
                i = j
            elif ch == '^':
                tokens.append(('start', None))
            elif ch == '$':
                tokens.append(('end', None))
            elif ch == '\\' and i + 1 < len(pattern):
                i += 1
                if pattern[i] == 'd':
                    tokens.append(('class', '0123456789'))
                elif pattern[i] == 'w':
                    tokens.append(('class', 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))
                elif pattern[i] == 's':
                    tokens.append(('class', ' \t\n\r'))
                else:
                    tokens.append(('lit', pattern[i]))
            else:
                tokens.append(('lit', ch))
            i += 1
        return tokens

    def match(self, pattern, text):
        if pattern not in self.compiled:
            self.compile(pattern)
        tokens = self.compiled[pattern]
        result = self._match_tokens(tokens, text, 0)
        if result is not None:
            self.match_count += 1
        return result is not None

    def _match_tokens(self, tokens, text, pos):
        if not tokens:
            return pos
        token = tokens[0]
        rest = tokens[1:]
        ttype, tval = token
        if ttype == 'start':
            if pos == 0:
                return self._match_tokens(rest, text, pos)
            return None
        if ttype == 'end':
            if pos == len(text):
                return self._match_tokens(rest, text, pos)
            return None
        if ttype == 'lit':
            if pos < len(text) and text[pos] == tval:
                return self._match_tokens(rest, text, pos + 1)
            return None
        if ttype == 'any':
            if pos < len(text):
                return self._match_tokens(rest, text, pos + 1)
            return None
        if ttype == 'class':
            if pos < len(text) and text[pos] in tval:
                return self._match_tokens(rest, text, pos + 1)
            return None
        if ttype == 'opt':
            r = self._match_tokens([tval] + list(rest), text, pos)
            if r is not None:
                return r
            return self._match_tokens(rest, text, pos)
        if ttype == 'star':
            r = self._match_tokens(rest, text, pos)
            if r is not None:
                return r
            if pos < len(text):
                r2 = self._match_tokens([tval] + [token] + list(rest), text, pos)
                if r2 is not None:
                    return r2
            return None
        if ttype == 'plus':
            r = self._match_tokens([tval, ('star', tval)] + list(rest), text, pos)
            return r
        return None

    def find_all(self, pattern, text):
        matches = []
        for i in range(len(text)):
            if self.match(pattern, text[i:]):
                matches.append(i)
        return matches

    def get_stats(self):
        return {'patterns': len(self.compiled), 'matches': self.match_count}


class TextTokenizer:
    """Configurable text tokenizer."""

    def __init__(self):
        self.rules = []
        self.tokens_produced = 0

    def add_rule(self, name, predicate):
        self.rules.append({'name': name, 'predicate': predicate})

    def tokenize(self, text):
        tokens = []
        i = 0
        while i < len(text):
            matched = False
            for rule in self.rules:
                j = i
                while j < len(text) and rule['predicate'](text[j]):
                    j += 1
                if j > i:
                    tokens.append({'type': rule['name'], 'value': text[i:j], 'pos': i})
                    i = j
                    matched = True
                    break
            if not matched:
                i += 1
        self.tokens_produced += len(tokens)
        return tokens

    def tokenize_words(self, text):
        words = []
        current = []
        for ch in text:
            if ch.isalnum() or ch == '_':
                current.append(ch)
            else:
                if current:
                    words.append(''.join(current))
                    current = []
        if current:
            words.append(''.join(current))
        self.tokens_produced += len(words)
        return words

    def tokenize_sentences(self, text):
        sentences = []
        current = []
        for ch in text:
            current.append(ch)
            if ch in '.!?':
                sentences.append(''.join(current).strip())
                current = []
        if current:
            rest = ''.join(current).strip()
            if rest:
                sentences.append(rest)
        self.tokens_produced += len(sentences)
        return sentences

    def get_stats(self):
        return {'rules': len(self.rules), 'tokens_produced': self.tokens_produced}


