class BTreeIndex:
    """B-Tree inspired index for fast lookups."""

    def __init__(self, order=4):
        self.order = order
        self.root = {'keys': [], 'children': [], 'leaf': True}
        self.size = 0

    def insert(self, key, value=None):
        if value is None:
            value = key
        if len(self.root['keys']) >= self.order - 1:
            new_root = {'keys': [], 'children': [self.root], 'leaf': False}
            self._split_child(new_root, 0)
            self.root = new_root
        self._insert_non_full(self.root, key, value)
        self.size += 1

    def _insert_non_full(self, node, key, value):
        i = len(node['keys']) - 1
        if node['leaf']:
            node['keys'].append((key, value))
            node['keys'].sort(key=lambda x: x[0])
        else:
            while i >= 0 and key < node['keys'][i][0]:
                i -= 1
            i += 1
            if len(node['children'][i]['keys']) >= self.order - 1:
                self._split_child(node, i)
                if key > node['keys'][i][0]:
                    i += 1
            self._insert_non_full(node['children'][i], key, value)

    def _split_child(self, parent, idx):
        child = parent['children'][idx]
        mid = len(child['keys']) // 2
        new_node = {
            'keys': child['keys'][mid + 1:],
            'children': child['children'][mid + 1:] if not child['leaf'] else [],
            'leaf': child['leaf']
        }
        median = child['keys'][mid]
        child['keys'] = child['keys'][:mid]
        if not child['leaf']:
            child['children'] = child['children'][:mid + 1]
        parent['keys'].insert(idx, median)
        parent['children'].insert(idx + 1, new_node)

    def search(self, key):
        return self._search_node(self.root, key)

    def _search_node(self, node, key):
        for k, v in node['keys']:
            if k == key:
                return v
        if node['leaf']:
            return None
        for i, (k, _) in enumerate(node['keys']):
            if key < k:
                return self._search_node(node['children'][i], key)
        return self._search_node(node['children'][-1], key)

    def range_query(self, low, high):
        results = []
        self._range_collect(self.root, low, high, results)
        return results

    def _range_collect(self, node, low, high, results):
        for k, v in node['keys']:
            if low <= k <= high:
                results.append((k, v))
        if not node['leaf']:
            for child in node['children']:
                self._range_collect(child, low, high, results)

    def get_height(self):
        h = 0
        node = self.root
        while not node['leaf'] and node['children']:
            h += 1
            node = node['children'][0]
        return h

    def in_order(self):
        result = []
        self._in_order(self.root, result)
        return result

    def _in_order(self, node, result):
        if node['leaf']:
            result.extend(node['keys'])
            return
        for i, child in enumerate(node['children']):
            self._in_order(child, result)
            if i < len(node['keys']):
                result.append(node['keys'][i])


class SkipList:
    """Probabilistic skip list for O(log n) operations."""

    def __init__(self, max_level=8):
        self.max_level = max_level
        self.head = {'key': None, 'value': None, 'next': [None] * (max_level + 1)}
        self.level = 0
        self.size = 0

    def _random_level(self):
        import random
        lvl = 0
        while random.random() < 0.5 and lvl < self.max_level:
            lvl += 1
        return lvl

    def insert(self, key, value=None):
        update = [None] * (self.max_level + 1)
        current = self.head
        for i in range(self.level, -1, -1):
            while current['next'][i] and current['next'][i]['key'] < key:
                current = current['next'][i]
            update[i] = current
        lvl = self._random_level()
        if lvl > self.level:
            for i in range(self.level + 1, lvl + 1):
                update[i] = self.head
            self.level = lvl
        new_node = {'key': key, 'value': value if value is not None else key,
                    'next': [None] * (lvl + 1)}
        for i in range(lvl + 1):
            new_node['next'][i] = update[i]['next'][i]
            update[i]['next'][i] = new_node
        self.size += 1

    def search(self, key):
        current = self.head
        for i in range(self.level, -1, -1):
            while current['next'][i] and current['next'][i]['key'] < key:
                current = current['next'][i]
        current = current['next'][0]
        if current and current['key'] == key:
            return current['value']
        return None

    def delete(self, key):
        update = [None] * (self.max_level + 1)
        current = self.head
        for i in range(self.level, -1, -1):
            while current['next'][i] and current['next'][i]['key'] < key:
                current = current['next'][i]
            update[i] = current
        target = current['next'][0]
        if target and target['key'] == key:
            for i in range(self.level + 1):
                if update[i]['next'][i] != target:
                    break
                update[i]['next'][i] = target['next'][i]
            while self.level > 0 and self.head['next'][self.level] is None:
                self.level -= 1
            self.size -= 1
            return True
        return False

    def to_list(self):
        result = []
        current = self.head['next'][0]
        while current:
            result.append((current['key'], current['value']))
            current = current['next'][0]
        return result


class TreapMap:
    """Treap — tree + heap hybrid data structure."""

    def __init__(self):
        self.root = None
        self.size = 0

    def _new_node(self, key, value):
        import random
        return {'key': key, 'value': value, 'priority': random.random(),
                'left': None, 'right': None}

    def _rotate_right(self, node):
        left = node['left']
        node['left'] = left['right']
        left['right'] = node
        return left

    def _rotate_left(self, node):
        right = node['right']
        node['right'] = right['left']
        right['left'] = node
        return right

    def insert(self, key, value=None):
        self.root = self._insert(self.root, key, value if value is not None else key)
        self.size += 1

    def _insert(self, node, key, value):
        if node is None:
            return self._new_node(key, value)
        if key < node['key']:
            node['left'] = self._insert(node['left'], key, value)
            if node['left']['priority'] > node['priority']:
                node = self._rotate_right(node)
        elif key > node['key']:
            node['right'] = self._insert(node['right'], key, value)
            if node['right']['priority'] > node['priority']:
                node = self._rotate_left(node)
        else:
            node['value'] = value
            self.size -= 1
        return node

    def search(self, key):
        node = self.root
        while node:
            if key == node['key']:
                return node['value']
            elif key < node['key']:
                node = node['left']
            else:
                node = node['right']
        return None

    def delete(self, key):
        self.root, deleted = self._delete(self.root, key)
        if deleted:
            self.size -= 1
        return deleted

    def _delete(self, node, key):
        if node is None:
            return None, False
        if key < node['key']:
            node['left'], deleted = self._delete(node['left'], key)
            return node, deleted
        elif key > node['key']:
            node['right'], deleted = self._delete(node['right'], key)
            return node, deleted
        else:
            if node['left'] is None:
                return node['right'], True
            elif node['right'] is None:
                return node['left'], True
            elif node['left']['priority'] > node['right']['priority']:
                node = self._rotate_right(node)
                node['right'], deleted = self._delete(node['right'], key)
                return node, deleted
            else:
                node = self._rotate_left(node)
                node['left'], deleted = self._delete(node['left'], key)
                return node, deleted

    def in_order(self):
        result = []
        self._in_order(self.root, result)
        return result

    def _in_order(self, node, result):
        if node is None:
            return
        self._in_order(node['left'], result)
        result.append((node['key'], node['value']))
        self._in_order(node['right'], result)

    def get_height(self):
        return self._height(self.root)

    def _height(self, node):
        if node is None:
            return 0
        return 1 + max(self._height(node['left']), self._height(node['right']))


def format_btree(bt):
    lines = ["=== BTreeIndex ==="]
    lines.append(f"  Order: {bt.order}")
