class JobRunner:
    """Manages job execution with status tracking and retry logic."""
    def __init__(self, max_retries=3):
        self.max_retries = max_retries
        self.jobs = {}
        self.history = []

    def submit(self, job_id, func, *args, **kwargs):
        self.jobs[job_id] = {
            'func': func, 'args': args, 'kwargs': kwargs,
            'status': 'pending', 'retries': 0, 'result': None, 'error': None
        }
        return job_id

    def run(self, job_id):
        if job_id not in self.jobs:
            return None
        job = self.jobs[job_id]
        job['status'] = 'running'
        for attempt in range(self.max_retries + 1):
            try:
                result = job['func'](*job['args'], **job['kwargs'])
                job['status'] = 'completed'
                job['result'] = result
                job['retries'] = attempt
                self.history.append({'job_id': job_id, 'status': 'completed', 'attempts': attempt + 1})
                return result
            except Exception as e:
                job['error'] = str(e)
                job['retries'] = attempt + 1
        job['status'] = 'failed'
        self.history.append({'job_id': job_id, 'status': 'failed', 'attempts': self.max_retries + 1})
        return None

    def run_all(self):
        results = {}
        for job_id in list(self.jobs.keys()):
            if self.jobs[job_id]['status'] == 'pending':
                results[job_id] = self.run(job_id)
        return results

    def get_status(self, job_id):
        if job_id not in self.jobs:
            return None
        return self.jobs[job_id]['status']

    def get_history(self):
        return list(self.history)

    def get_pending(self):
        return [jid for jid, j in self.jobs.items() if j['status'] == 'pending']

    def get_completed(self):
        return [jid for jid, j in self.jobs.items() if j['status'] == 'completed']

    def cancel(self, job_id):
        if job_id in self.jobs and self.jobs[job_id]['status'] == 'pending':
            self.jobs[job_id]['status'] = 'cancelled'
            return True
        return False


class CronScheduler:
    """Cron-like scheduler with interval and schedule management."""
    def __init__(self):
        self.schedules = {}
        self.execution_log = []
        self._tick = 0

    def add_schedule(self, name, interval, func, *args):
        self.schedules[name] = {
            'interval': interval, 'func': func, 'args': args,
            'last_run': None, 'run_count': 0, 'active': True
        }

    def remove_schedule(self, name):
        if name in self.schedules:
            del self.schedules[name]
            return True
        return False

    def pause(self, name):
        if name in self.schedules:
            self.schedules[name]['active'] = False
            return True
        return False

    def resume(self, name):
        if name in self.schedules:
            self.schedules[name]['active'] = True
            return True
        return False

    def tick(self):
        self._tick += 1
        executed = []
        for name, sched in self.schedules.items():
            if not sched['active']:
                continue
            if sched['last_run'] is None or (self._tick - sched['last_run']) >= sched['interval']:
                try:
                    result = sched['func'](*sched['args'])
                    sched['last_run'] = self._tick
                    sched['run_count'] += 1
                    self.execution_log.append({'tick': self._tick, 'schedule': name, 'status': 'ok'})
                    executed.append(name)
                except Exception as e:
                    self.execution_log.append({'tick': self._tick, 'schedule': name, 'status': 'error', 'error': str(e)})
        return executed

    def run_ticks(self, n):
        all_executed = []
        for _ in range(n):
            all_executed.extend(self.tick())
        return all_executed

    def get_schedule_names(self):
        return list(self.schedules.keys())

    def get_run_count(self, name):
        if name in self.schedules:
            return self.schedules[name]['run_count']
        return 0

    def get_log(self):
        return list(self.execution_log)

    def get_active(self):
        return [n for n, s in self.schedules.items() if s['active']]


class EventStream:
    """Ordered event stream with filtering and replay capabilities."""
    def __init__(self, max_size=10000):
        self.events = []
        self.max_size = max_size
        self.consumers = {}
        self._seq = 0

    def publish(self, event_type, data=None):
        self._seq += 1
        event = {'seq': self._seq, 'type': event_type, 'data': data}
        self.events.append(event)
        if len(self.events) > self.max_size:
            self.events = self.events[-self.max_size:]
        return self._seq

    def subscribe(self, consumer_id, event_types=None):
        self.consumers[consumer_id] = {
            'types': event_types, 'offset': self._seq
        }

    def consume(self, consumer_id, limit=100):
        if consumer_id not in self.consumers:
            return []
        consumer = self.consumers[consumer_id]
        offset = consumer['offset']
        types = consumer['types']
        result = []
        for event in self.events:
            if event['seq'] <= offset:
                continue
            if types and event['type'] not in types:
                continue
            result.append(event)
            if len(result) >= limit:
                break
        if result:
            consumer['offset'] = result[-1]['seq']
        return result

    def replay(self, event_type=None, start_seq=0):
        result = []
        for event in self.events:
            if event['seq'] < start_seq:
                continue
            if event_type and event['type'] != event_type:
                continue
            result.append(event)
        return result

    def get_types(self):
        return list(set(e['type'] for e in self.events))

    def count(self, event_type=None):
        if event_type:
            return sum(1 for e in self.events if e['type'] == event_type)
        return len(self.events)

    def get_latest(self, n=10):
        return self.events[-n:]

    def clear(self):
        self.events.clear()
        self._seq = 0


