class PubSubBroker:
    """Publish-subscribe messaging broker with topic management."""
    def __init__(self):
        self.topics = {}
        self.subscribers = {}
        self.message_count = 0
        self.delivery_log = []

    def create_topic(self, topic):
        if topic not in self.topics:
            self.topics[topic] = []
            return True
        return False

    def delete_topic(self, topic):
        if topic in self.topics:
            del self.topics[topic]
            return True
        return False

    def subscribe(self, subscriber_id, topic):
        if topic not in self.topics:
            self.create_topic(topic)
        if subscriber_id not in self.subscribers:
            self.subscribers[subscriber_id] = {'topics': set(), 'inbox': []}
        self.subscribers[subscriber_id]['topics'].add(topic)

    def unsubscribe(self, subscriber_id, topic):
        if subscriber_id in self.subscribers:
            self.subscribers[subscriber_id]['topics'].discard(topic)
            return True
        return False

    def publish(self, topic, message):
        if topic not in self.topics:
            self.create_topic(topic)
        self.message_count += 1
        msg = {'id': self.message_count, 'topic': topic, 'body': message}
        self.topics[topic].append(msg)
        delivered = 0
        for sub_id, sub in self.subscribers.items():
            if topic in sub['topics']:
                sub['inbox'].append(msg)
                delivered += 1
        self.delivery_log.append({'msg_id': self.message_count, 'topic': topic, 'delivered_to': delivered})
        return self.message_count

    def receive(self, subscriber_id, limit=10):
        if subscriber_id not in self.subscribers:
            return []
        msgs = self.subscribers[subscriber_id]['inbox'][:limit]
        self.subscribers[subscriber_id]['inbox'] = self.subscribers[subscriber_id]['inbox'][limit:]
        return msgs

    def get_topics(self):
        return list(self.topics.keys())

    def get_subscriber_count(self, topic):
        count = 0
        for sub in self.subscribers.values():
            if topic in sub['topics']:
                count += 1
        return count

    def get_message_count(self):
        return self.message_count

    def get_pending(self, subscriber_id):
        if subscriber_id in self.subscribers:
            return len(self.subscribers[subscriber_id]['inbox'])
        return 0


class EmailBuilder:
    """Fluent email construction with validation."""
    def __init__(self):
        self._from = None
        self._to = []
        self._cc = []
        self._subject = None
        self._body = None
        self._attachments = []
        self._headers = {}
        self._built_emails = []

    def set_from(self, addr):
        self._from = addr
        return self

    def add_to(self, addr):
        self._to.append(addr)
        return self

    def add_cc(self, addr):
        self._cc.append(addr)
        return self

    def set_subject(self, subject):
        self._subject = subject
        return self

    def set_body(self, body):
        self._body = body
        return self

    def add_attachment(self, name, content):
        self._attachments.append({'name': name, 'content': content})
        return self

    def add_header(self, key, value):
        self._headers[key] = value
        return self

    def validate(self):
        errors = []
        if not self._from:
            errors.append("Missing sender")
        if not self._to:
            errors.append("Missing recipients")
        if not self._subject:
            errors.append("Missing subject")
        if self._from and '@' not in self._from:
            errors.append("Invalid sender email")
        for addr in self._to:
            if '@' not in addr:
                errors.append(f"Invalid recipient: {addr}")
        return errors

    def build(self):
        errors = self.validate()
        if errors:
            return {'valid': False, 'errors': errors}
        email = {
            'from': self._from, 'to': list(self._to), 'cc': list(self._cc),
            'subject': self._subject, 'body': self._body,
            'attachments': list(self._attachments), 'headers': dict(self._headers),
            'valid': True
        }
        self._built_emails.append(email)
        return email

    def reset(self):
        self._from = None
        self._to = []
        self._cc = []
        self._subject = None
        self._body = None
        self._attachments = []
        self._headers = {}
        return self

    def get_built_count(self):
        return len(self._built_emails)


class TemplateMailer:
    """Template-based email system with variable substitution."""
    def __init__(self):
        self.templates = {}
        self.sent = []

    def add_template(self, name, subject_tmpl, body_tmpl):
        self.templates[name] = {'subject': subject_tmpl, 'body': body_tmpl}

    def remove_template(self, name):
        if name in self.templates:
            del self.templates[name]
            return True
        return False

    def render(self, template_name, variables):
        if template_name not in self.templates:
            return None
        tmpl = self.templates[template_name]
        subject = tmpl['subject']
        body = tmpl['body']
        for key, value in variables.items():
            placeholder = '{{' + key + '}}'
            subject = subject.replace(placeholder, str(value))
            body = body.replace(placeholder, str(value))
        return {'subject': subject, 'body': body}

    def send(self, template_name, to, variables):
        rendered = self.render(template_name, variables)
        if not rendered:
            return False
        email = {'to': to, 'subject': rendered['subject'], 'body': rendered['body'], 'template': template_name}
        self.sent.append(email)
        return True

    def get_sent_count(self):
        return len(self.sent)

    def get_sent(self):
        return list(self.sent)

    def list_templates(self):
        return list(self.templates.keys())

    def preview(self, template_name, variables):
        return self.render(template_name, variables)


