class FullTextIndex:
    """Full-text search index with inverted index and TF-IDF scoring."""
    def __init__(self):
        self.documents = {}
        self.inverted_index = {}
        self.doc_count = 0

    def add_document(self, doc_id, text):
        tokens = self._tokenize(text)
        self.documents[doc_id] = {'text': text, 'tokens': tokens, 'length': len(tokens)}
        for token in set(tokens):
            if token not in self.inverted_index:
                self.inverted_index[token] = set()
            self.inverted_index[token].add(doc_id)
        self.doc_count += 1

    def _tokenize(self, text):
        result = []
        word = []
        for ch in text.lower():
            if ch.isalnum():
                word.append(ch)
            else:
                if word:
                    result.append(''.join(word))
                    word = []
        if word:
            result.append(''.join(word))
        return result

    def search(self, query, limit=10):
        query_tokens = self._tokenize(query)
        if not query_tokens:
            return []
        scores = {}
        import math
        for token in query_tokens:
            if token not in self.inverted_index:
                continue
            doc_ids = self.inverted_index[token]
            idf = math.log(1 + len(self.documents) / len(doc_ids))
            for doc_id in doc_ids:
                tf = self.documents[doc_id]['tokens'].count(token) / max(1, self.documents[doc_id]['length'])
                scores[doc_id] = scores.get(doc_id, 0) + tf * idf
        ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)
        return [{'doc_id': d, 'score': round(s, 4)} for d, s in ranked[:limit]]

    def remove_document(self, doc_id):
        if doc_id not in self.documents:
            return False
        tokens = self.documents[doc_id]['tokens']
        for token in set(tokens):
            if token in self.inverted_index:
                self.inverted_index[token].discard(doc_id)
                if not self.inverted_index[token]:
                    del self.inverted_index[token]
        del self.documents[doc_id]
        return True

    def get_document_count(self):
        return len(self.documents)

    def get_vocabulary_size(self):
        return len(self.inverted_index)

    def get_documents_containing(self, term):
        term = term.lower()
        if term in self.inverted_index:
            return list(self.inverted_index[term])
        return []


class QueryTokenizer:
    """Advanced query tokenizer with operators and phrase support."""
    def __init__(self):
        self.operators = {'AND', 'OR', 'NOT'}
        self.parsed_count = 0

    def tokenize(self, query):
        tokens = []
        i = 0
        while i < len(query):
            if query[i] == '"':
                j = query.index('"', i + 1) if '"' in query[i+1:] else len(query)
                tokens.append({'type': 'phrase', 'value': query[i+1:j]})
                i = j + 1
            elif query[i] == '(':
                tokens.append({'type': 'open_paren', 'value': '('})
                i += 1
            elif query[i] == ')':
                tokens.append({'type': 'close_paren', 'value': ')'})
                i += 1
            elif query[i].isspace():
                i += 1
            else:
                j = i
                while j < len(query) and not query[j].isspace() and query[j] not in '()"':
                    j += 1
                word = query[i:j]
                if word.upper() in self.operators:
                    tokens.append({'type': 'operator', 'value': word.upper()})
                else:
                    tokens.append({'type': 'term', 'value': word.lower()})
                i = j
        self.parsed_count += 1
        return tokens

    def parse_query(self, query):
        tokens = self.tokenize(query)
        terms = [t['value'] for t in tokens if t['type'] in ('term', 'phrase')]
        operators = [t['value'] for t in tokens if t['type'] == 'operator']
        return {'terms': terms, 'operators': operators, 'tokens': tokens}

    def get_parsed_count(self):
        return self.parsed_count

    def extract_terms(self, query):
        parsed = self.parse_query(query)
        return parsed['terms']

    def has_operator(self, query, op):
        parsed = self.parse_query(query)
        return op.upper() in parsed['operators']


class PageRanker:
    """Simple PageRank implementation for document ranking."""
    def __init__(self, damping=0.85, iterations=20):
        self.damping = damping
        self.iterations = iterations
        self.nodes = set()
        self.edges = {}
        self.ranks = {}

    def add_node(self, node_id):
        self.nodes.add(node_id)
        if node_id not in self.edges:
            self.edges[node_id] = set()

    def add_edge(self, from_node, to_node):
        self.add_node(from_node)
        self.add_node(to_node)
        self.edges[from_node].add(to_node)

    def compute(self):
        n = len(self.nodes)
        if n == 0:
            return {}
        for node in self.nodes:
            self.ranks[node] = 1.0 / n
        for _ in range(self.iterations):
            new_ranks = {}
            for node in self.nodes:
                rank_sum = 0.0
                for other in self.nodes:
                    if node in self.edges.get(other, set()):
                        out_degree = len(self.edges[other])
                        if out_degree > 0:
                            rank_sum += self.ranks[other] / out_degree
                new_ranks[node] = (1 - self.damping) / n + self.damping * rank_sum
            self.ranks = new_ranks
        return dict(self.ranks)

    def get_rank(self, node_id):
        return self.ranks.get(node_id, 0.0)

    def get_top(self, n=10):
        ranked = sorted(self.ranks.items(), key=lambda x: x[1], reverse=True)
        return ranked[:n]

    def get_node_count(self):
        return len(self.nodes)

    def get_edge_count(self):
        return sum(len(e) for e in self.edges.values())


