class PermissionGuard:
    """Role-based access control with permission checking."""
    def __init__(self):
        self.roles = {}
        self.user_roles = {}
        self.check_log = []

    def define_role(self, role, permissions):
        self.roles[role] = set(permissions)

    def assign_role(self, user_id, role):
        if role not in self.roles:
            return False
        if user_id not in self.user_roles:
            self.user_roles[user_id] = set()
        self.user_roles[user_id].add(role)
        return True

    def revoke_role(self, user_id, role):
        if user_id in self.user_roles:
            self.user_roles[user_id].discard(role)
            return True
        return False

    def check(self, user_id, permission):
        granted = False
        if user_id in self.user_roles:
            for role in self.user_roles[user_id]:
                if permission in self.roles.get(role, set()):
                    granted = True
                    break
        self.check_log.append({'user': user_id, 'permission': permission, 'granted': granted})
        return granted

    def get_permissions(self, user_id):
        perms = set()
        if user_id in self.user_roles:
            for role in self.user_roles[user_id]:
                perms.update(self.roles.get(role, set()))
        return perms

    def get_user_roles(self, user_id):
        return list(self.user_roles.get(user_id, set()))

    def get_all_roles(self):
        return list(self.roles.keys())

    def get_check_log(self):
        return list(self.check_log)


class TokenVault:
    """Secure token storage with expiration and rotation."""
    def __init__(self):
        self.tokens = {}
        self.revoked = set()
        self._counter = 0

    def generate(self, owner, ttl=3600, metadata=None):
        self._counter += 1
        token_id = f"tok_{self._counter:06d}"
        self.tokens[token_id] = {
            'owner': owner, 'ttl': ttl, 'metadata': metadata or {},
            'created_at': self._counter, 'rotated': False
        }
        return token_id

    def validate(self, token_id):
        if token_id in self.revoked:
            return {'valid': False, 'reason': 'revoked'}
        if token_id not in self.tokens:
            return {'valid': False, 'reason': 'not_found'}
        return {'valid': True, 'owner': self.tokens[token_id]['owner']}

    def revoke(self, token_id):
        if token_id in self.tokens:
            self.revoked.add(token_id)
            return True
        return False

    def rotate(self, token_id):
        if token_id not in self.tokens or token_id in self.revoked:
            return None
        old_token = self.tokens[token_id]
        self.revoked.add(token_id)
        new_id = self.generate(old_token['owner'], old_token['ttl'], old_token['metadata'])
        self.tokens[new_id]['rotated'] = True
        return new_id

    def get_active_count(self):
        return sum(1 for t in self.tokens if t not in self.revoked)

    def get_revoked_count(self):
        return len(self.revoked)

    def get_owner_tokens(self, owner):
        return [tid for tid, t in self.tokens.items() if t['owner'] == owner and tid not in self.revoked]

    def get_metadata(self, token_id):
        if token_id in self.tokens:
            return self.tokens[token_id]['metadata']
        return None


class AuditTrail:
    """Comprehensive audit logging with query capabilities."""
    def __init__(self, max_entries=50000):
        self.entries = []
        self.max_entries = max_entries
        self._seq = 0

    def log(self, actor, action, resource, details=None):
        self._seq += 1
        entry = {
            'seq': self._seq, 'actor': actor, 'action': action,
            'resource': resource, 'details': details or {}
        }
        self.entries.append(entry)
        if len(self.entries) > self.max_entries:
            self.entries = self.entries[-self.max_entries:]
        return self._seq

    def query(self, actor=None, action=None, resource=None, limit=100):
        results = []
        for entry in reversed(self.entries):
            if actor and entry['actor'] != actor:
                continue
            if action and entry['action'] != action:
                continue
            if resource and entry['resource'] != resource:
                continue
            results.append(entry)
            if len(results) >= limit:
                break
        return results

    def get_actors(self):
        return list(set(e['actor'] for e in self.entries))

    def get_actions(self):
        return list(set(e['action'] for e in self.entries))

    def count(self, actor=None, action=None):
        c = 0
        for entry in self.entries:
            if actor and entry['actor'] != actor:
                continue
            if action and entry['action'] != action:
                continue
            c += 1
        return c

    def get_recent(self, n=20):
        return self.entries[-n:]

    def clear(self):
        self.entries.clear()
        self._seq = 0

    def get_total(self):
        return len(self.entries)


