class TelemetryCollector:
    """Collects and aggregates telemetry data from multiple sources."""
    def __init__(self):
        self.metrics = {}
        self.sources = set()
        self.collection_count = 0

    def register_source(self, source_id):
        self.sources.add(source_id)

    def collect(self, source_id, metric_name, value):
        if source_id not in self.sources:
            self.register_source(source_id)
        key = (source_id, metric_name)
        if key not in self.metrics:
            self.metrics[key] = []
        self.metrics[key].append(value)
        self.collection_count += 1

    def aggregate(self, metric_name, method='mean'):
        values = []
        for (src, name), vals in self.metrics.items():
            if name == metric_name:
                values.extend(vals)
        if not values:
            return None
        if method == 'mean':
            return sum(values) / len(values)
        elif method == 'sum':
            return sum(values)
        elif method == 'min':
            return min(values)
        elif method == 'max':
            return max(values)
        elif method == 'count':
            return len(values)
        return None

    def get_source_metrics(self, source_id):
        result = {}
        for (src, name), vals in self.metrics.items():
            if src == source_id:
                result[name] = vals
        return result

    def get_metric_names(self):
        return list(set(name for (_, name) in self.metrics.keys()))

    def get_sources(self):
        return list(self.sources)

    def get_collection_count(self):
        return self.collection_count

    def clear_source(self, source_id):
        keys_to_remove = [k for k in self.metrics if k[0] == source_id]
        for k in keys_to_remove:
            del self.metrics[k]
        return len(keys_to_remove)


class Heartbeat:
    """Service heartbeat monitoring with health status tracking."""
    def __init__(self, timeout=5):
        self.services = {}
        self.timeout = timeout
        self._tick = 0

    def register(self, service_id, metadata=None):
        self.services[service_id] = {
            'metadata': metadata or {}, 'last_beat': None,
            'status': 'unknown', 'beat_count': 0, 'missed': 0
        }

    def beat(self, service_id):
        if service_id not in self.services:
            self.register(service_id)
        self.services[service_id]['last_beat'] = self._tick
        self.services[service_id]['status'] = 'healthy'
        self.services[service_id]['beat_count'] += 1

    def tick(self):
        self._tick += 1
        for svc_id, svc in self.services.items():
            if svc['last_beat'] is not None:
                if (self._tick - svc['last_beat']) > self.timeout:
                    svc['status'] = 'unhealthy'
                    svc['missed'] += 1

    def run_ticks(self, n):
        for _ in range(n):
            self.tick()

    def get_status(self, service_id):
        if service_id in self.services:
            return self.services[service_id]['status']
        return None

    def get_healthy(self):
        return [s for s, info in self.services.items() if info['status'] == 'healthy']

    def get_unhealthy(self):
        return [s for s, info in self.services.items() if info['status'] == 'unhealthy']

    def get_all_services(self):
        return list(self.services.keys())

    def get_beat_count(self, service_id):
        if service_id in self.services:
            return self.services[service_id]['beat_count']
        return 0

    def get_stats(self):
        return {
            'total': len(self.services),
            'healthy': len(self.get_healthy()),
            'unhealthy': len(self.get_unhealthy()),
            'tick': self._tick
        }


class IncidentManager:
    """Incident tracking and management system."""
    def __init__(self):
        self.incidents = {}
        self._counter = 0
        self.severity_levels = ['low', 'medium', 'high', 'critical']

    def create(self, title, severity='medium', description=None):
        if severity not in self.severity_levels:
            severity = 'medium'
        self._counter += 1
        inc_id = f"INC-{self._counter:04d}"
        self.incidents[inc_id] = {
            'title': title, 'severity': severity, 'description': description or '',
            'status': 'open', 'timeline': [{'action': 'created', 'step': self._counter}],
            'assignee': None, 'resolution': None
        }
        return inc_id

    def assign(self, inc_id, assignee):
        if inc_id in self.incidents:
            self.incidents[inc_id]['assignee'] = assignee
            self.incidents[inc_id]['timeline'].append({'action': 'assigned', 'to': assignee})
            return True
        return False

    def update_status(self, inc_id, status):
        valid = ['open', 'investigating', 'mitigated', 'resolved', 'closed']
        if inc_id in self.incidents and status in valid:
            self.incidents[inc_id]['status'] = status
            self.incidents[inc_id]['timeline'].append({'action': 'status_change', 'status': status})
            return True
        return False

    def resolve(self, inc_id, resolution):
        if inc_id in self.incidents:
            self.incidents[inc_id]['status'] = 'resolved'
            self.incidents[inc_id]['resolution'] = resolution
            self.incidents[inc_id]['timeline'].append({'action': 'resolved', 'resolution': resolution})
            return True
        return False

    def get_open(self):
        return [iid for iid, inc in self.incidents.items() if inc['status'] in ('open', 'investigating')]

    def get_by_severity(self, severity):
        return [iid for iid, inc in self.incidents.items() if inc['severity'] == severity]

    def get_timeline(self, inc_id):
        if inc_id in self.incidents:
            return self.incidents[inc_id]['timeline']
        return []

    def get_stats(self):
        stats = {'total': len(self.incidents)}
        for sev in self.severity_levels:
            stats[sev] = len(self.get_by_severity(sev))
        stats['open'] = len(self.get_open())
        return stats

    def get_all(self):
        return list(self.incidents.keys())


def format_telemetry_collector(collector):
    lines = ["=== Telemetry Collector ==="]
    lines.append(f"  Sources: {collector.get_sources()}")
    lines.append(f"  Metrics: {collector.get_metric_names()}")
    lines.append(f"  Collections: {collector.get_collection_count()}")
    return '\n'.join(lines)

def format_heartbeat(hb):
    stats = hb.get_stats()
    lines = ["=== Heartbeat Monitor ==="]
    lines.append(f"  Services: {stats['total']}")
    lines.append(f"  Healthy: {stats['healthy']}")
    lines.append(f"  Unhealthy: {stats['unhealthy']}")
    lines.append(f"  Current tick: {stats['tick']}")
    return '\n'.join(lines)

def format_incident_manager(manager):
    stats = manager.get_stats()
    lines = ["=== Incident Manager ==="]
    lines.append(f"  Total incidents: {stats['total']}")
    lines.append(f"  Open: {stats['open']}")
    lines.append(f"  Critical: {stats.get('critical', 0)}")
    lines.append(f"  High: {stats.get('high', 0)}")
    return '\n'.join(lines)


