    print(f"  Jan retention:")
    for p, r in ret.items():
        print(f"    Period {p}: {r['active']}/{r['total']} = {r['retention']:.0f}%")
    comparison = ca.compare_cohorts("score", 3)
    print(f"  Score comparison (period 3): {comparison}")
