    # --------------------------------------------------------
    # Demo 307: JobRunner — retry on failure
    # --------------------------------------------------------
    print("\n--- Demo 307: JobRunner Retry ---")
    jr2 = JobRunner(max_retries=2)
    call_count = [0]
    def flaky_func():
        call_count[0] += 1
        if call_count[0] < 3:
            raise ValueError("not yet")
        return "success"
    jr2.submit("flaky", flaky_func)
    result = jr2.run("flaky")
    assert result == "success", f"Expected success got {result}"
    assert jr2.get_status("flaky") == "completed"
    jr3 = JobRunner(max_retries=0)
    jr3.submit("fail", lambda: 1/0)
    jr3.run("fail")
    assert jr3.get_status("fail") == "failed"
    jr3.submit("cancel_me", lambda: None)
    assert jr3.cancel("cancel_me") == True
    assert jr3.get_status("cancel_me") == "cancelled"
    print("Demo 307 passed.")

