    # --------------------------------------------------------
    # Demo 309: CronScheduler — pause/resume
    # --------------------------------------------------------
    print("\n--- Demo 309: CronScheduler Pause/Resume ---")
    cs2 = CronScheduler()
    count_p = [0]
    cs2.add_schedule("task", 1, lambda: count_p.__setitem__(0, count_p[0] + 1))
    cs2.run_ticks(3)
    before_pause = count_p[0]
    cs2.pause("task")
    cs2.run_ticks(5)
    assert count_p[0] == before_pause, "Should not have run while paused"
    cs2.resume("task")
    cs2.run_ticks(2)
    assert count_p[0] > before_pause, "Should have run after resume"
    assert cs2.remove_schedule("task") == True
    assert len(cs2.get_schedule_names()) == 0
    print("Demo 309 passed.")

