    # Demo 315: QueryTokenizer — query parsing
    # --------------------------------------------------------
    print("\n--- Demo 315: QueryTokenizer ---")
    qt = QueryTokenizer()
    tokens = qt.tokenize('hello AND "world peace" OR test')
    assert len(tokens) == 5
    assert tokens[0] == {'type': 'term', 'value': 'hello'}
    assert tokens[1] == {'type': 'operator', 'value': 'AND'}
    assert tokens[2] == {'type': 'phrase', 'value': 'world peace'}
    assert tokens[3] == {'type': 'operator', 'value': 'OR'}
    assert tokens[4] == {'type': 'term', 'value': 'test'}
    parsed = qt.parse_query("alpha AND beta NOT gamma")
    assert parsed['terms'] == ['alpha', 'beta', 'gamma']
    assert 'AND' in parsed['operators']
    assert 'NOT' in parsed['operators']
    terms = qt.extract_terms('"exact match" other')
    assert "exact match" in terms and "other" in terms
    assert qt.has_operator("a OR b", "OR") == True
    assert qt.has_operator("a b", "AND") == False
    assert qt.get_parsed_count() == 5
    print(format_query_tokenizer(qt))
