    # --------------------------------------------------------
    # Demo 316: PageRanker — graph ranking
    # --------------------------------------------------------
    print("\n--- Demo 316: PageRanker ---")
    pr = PageRanker(damping=0.85, iterations=30)
    for page in ["A", "B", "C", "D"]:
        pr.add_node(page)
    pr.add_edge("A", "B")
    pr.add_edge("A", "C")
    pr.add_edge("B", "C")
    pr.add_edge("C", "A")
    pr.add_edge("D", "C")
    ranks = pr.compute()
    assert pr.get_node_count() == 4
    assert pr.get_edge_count() == 5
    top = pr.get_top(4)
    assert top[0][0] in ("A", "C"), f"Expected A or C at top, got {top[0][0]}"
    assert all(r > 0 for _, r in top)
    total_rank = sum(r for _, r in top)
    assert abs(total_rank - 1.0) < 0.01, f"Total rank should be ~1.0, got {total_rank}"
    print(format_page_ranker(pr))
    print("Demo 316 passed.")

