    pg = PermissionGuard()
    pg.define_role("admin", ["read", "write", "delete", "manage"])
    pg.define_role("editor", ["read", "write"])
    pg.define_role("viewer", ["read"])
    pg.assign_role("alice", "admin")
    pg.assign_role("bob", "editor")
    pg.assign_role("charlie", "viewer")
    assert pg.check("alice", "delete") == True
    assert pg.check("bob", "delete") == False
    assert pg.check("charlie", "read") == True
    assert pg.check("charlie", "write") == False
    assert pg.check("unknown", "read") == False
    perms = pg.get_permissions("alice")
    assert "manage" in perms and "read" in perms
    assert pg.get_user_roles("bob") == ["editor"]
    pg.revoke_role("bob", "editor")
    assert pg.check("bob", "read") == False
    assert len(pg.get_check_log()) == 6
    print(format_permission_guard(pg))
    print("Demo 317 passed.")

    # --------------------------------------------------------
    # Demo 318: TokenVault — token management
