    print("\n--- Demo 318: TokenVault ---")
    tv = TokenVault()
    t1 = tv.generate("alice", ttl=3600, metadata={"scope": "api"})
    t2 = tv.generate("bob", ttl=1800)
    t3 = tv.generate("alice", ttl=7200)
    assert tv.get_active_count() == 3
    v1 = tv.validate(t1)
    assert v1['valid'] == True and v1['owner'] == 'alice'
    tv.revoke(t2)
    assert tv.validate(t2)['valid'] == False
    assert tv.validate(t2)['reason'] == 'revoked'
    assert tv.get_active_count() == 2
    assert tv.get_revoked_count() == 1
    t1_new = tv.rotate(t1)
    assert t1_new is not None
    assert tv.validate(t1)['valid'] == False
    assert tv.validate(t1_new)['valid'] == True
    alice_tokens = tv.get_owner_tokens("alice")
    assert t1_new in alice_tokens and t3 in alice_tokens
    meta = tv.get_metadata(t1)
    assert meta['scope'] == 'api'
    assert tv.validate("nonexistent")['reason'] == 'not_found'
    print(format_token_vault(tv))
    print("Demo 318 passed.")

